function toObject(value) {
    return value && typeof value === "object" && !Array.isArray(value) ? value : {};
}

function parsePayload(payload) {
    if (!payload) return {};
    if (typeof payload === "string") {
        try { return JSON.parse(payload); } catch (err) { return {}; }
    }
    if (Buffer.isBuffer(payload)) {
        try { return JSON.parse(payload.toString()); } catch (err) { return {}; }
    }
    return toObject(payload);
}

function toNumber(value, fallback) {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
}

function normalizeCpsId(value) {
    return String(value || "").trim().toLowerCase().replace(/[^a-z0-9]/g, "").replace(/(cps)0+/, "$1");
}

function mean(values) {
    const clean = values.filter((value) => Number.isFinite(value));
    return clean.length ? clean.reduce((sum, value) => sum + value, 0) / clean.length : 0;
}

function slope(values) {
    const clean = values.filter((value) => Number.isFinite(value));
    const n = clean.length;
    if (n < 2) return 0;
    const meanX = (n - 1) / 2;
    const meanY = mean(clean);
    let numerator = 0;
    let denominator = 0;
    for (let i = 0; i < n; i += 1) {
        numerator += (i - meanX) * (clean[i] - meanY);
        denominator += Math.pow(i - meanX, 2);
    }
    return denominator ? numerator / denominator : 0;
}

function round(value, decimals) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return 0;
    const factor = Math.pow(10, decimals || 4);
    return Math.round(numeric * factor) / factor;
}

function countTrailing(history, predicate) {
    let count = 0;
    for (let i = history.length - 1; i >= 0; i -= 1) {
        if (!predicate(history[i])) break;
        count += 1;
    }
    return count;
}

function dominantLossFromMetrics(availability, performance, quality, explicitLoss) {
    const direct = String(explicitLoss || "").trim().toLowerCase();
    if (direct) return direct;
    const losses = {
        availability: 1 - toNumber(availability, 1),
        performance: 1 - toNumber(performance, 1),
        quality: 1 - toNumber(quality, 1)
    };
    return Object.entries(losses).sort((a, b) => b[1] - a[1])[0]?.[0] || "unknown";
}

function hasLocalAction(entry) {
    const action = String(entry?.localAction || "").toLowerCase();
    return action && !["maintain", "maintain_operation", "preserve_local_recovery"].includes(action);
}

function classifyInterventionEffectiveness(history, recentMeanOEE, oeeSlope) {
    const recent = history.slice(-4);
    const actions = recent.filter(hasLocalAction);
    if (!actions.length) return "neutral";
    const delta = recentMeanOEE - Number(actions[0].oee || 0);
    if (delta >= 0.012 || oeeSlope > 0.003) return "improving";
    if (delta <= 0.002 && oeeSlope <= 0.001) return "low_response";
    return "neutral";
}

function strategyForState(temporalState, dominantLoss) {
    const loss = dominantLoss || "loss";
    const map = {
        stable_asset: { adaptiveAction: "maintain_operation", strategyClass: "reactive" },
        degrading_asset: { adaptiveAction: "stabilize_local_" + loss, strategyClass: "adaptive" },
        recovering_asset: { adaptiveAction: "preserve_local_recovery", strategyClass: "adaptive" },
        persistent_local_loss: { adaptiveAction: "contain_local_loss", strategyClass: "adaptive" },
        low_response_to_local_action: { adaptiveAction: "structural_local_check", strategyClass: "escalated" }
    };
    return map[temporalState] || map.stable_asset;
}

function buildSignals(history, windowSize) {
    const values = history.map((entry) => Number(entry.oee)).filter((value) => Number.isFinite(value));
    const current = history[history.length - 1] || {};
    const currentLoss = String(current.dominantLoss || "").toLowerCase();
    const recentMeanOEE = mean(values.slice(-4));
    const oeeSlope = slope(values.slice(-5));
    const dominantLossPersistence = currentLoss
        ? countTrailing(history, (entry) => String(entry.dominantLoss || "").toLowerCase() === currentLoss)
        : 0;
    const interventionEffectiveness = classifyInterventionEffectiveness(history, recentMeanOEE, oeeSlope);

    let temporalState = "stable_asset";
    let adaptiveReason = "No persistent CPS adaptive pattern detected in the short local window.";

    if (interventionEffectiveness === "low_response") {
        temporalState = "low_response_to_local_action";
        adaptiveReason = "Recent local actions did not produce measurable OEE recovery.";
    } else if (dominantLossPersistence >= 3) {
        temporalState = "persistent_local_loss";
        adaptiveReason = "The same local OEE loss repeated across at least three recent CPS events.";
    } else if (oeeSlope < -0.003) {
        temporalState = "degrading_asset";
        adaptiveReason = "CPS OEE is decreasing in the short adaptive window.";
    } else if (oeeSlope > 0.003) {
        temporalState = "recovering_asset";
        adaptiveReason = "CPS OEE is improving in the short adaptive window.";
    }

    const strategy = strategyForState(temporalState, currentLoss);
    return {
        temporalState,
        adaptiveAction: strategy.adaptiveAction,
        strategyClass: strategy.strategyClass,
        interventionEffectiveness,
        adaptiveReason,
        historyWindow: windowSize,
        recentMeanOEE: round(recentMeanOEE, 4),
        oeeSlope: round(oeeSlope, 5),
        dominantLossPersistence
    };
}

function buildTimeline(history, limit) {
    return history.slice(-limit).reverse().map((entry) => ({
        ts: entry.ts || null,
        timestamp: entry.timestamp || "",
        temporalState: entry.temporalState || "",
        adaptiveAction: entry.adaptiveAction || "",
        strategyClass: entry.strategyClass || "",
        interventionEffectiveness: entry.interventionEffectiveness || ""
    }));
}

const inputTopic = String(msg.topic || "");
const payload = parsePayload(msg.payload);
const topicBase = inputTopic.split("/")[0] || "cps";
const cpsId = normalizeCpsId(payload.cpsId || payload.source || topicBase);
const windowSize = 8;
const now = Date.now();
const timestamp = payload.timestamp || new Date(now).toISOString();
const sourceTs = toNumber(payload.ts || Date.parse(timestamp), now);
const oeeBlock = toObject(payload.oee || payload.globalOEE);
const availability = toNumber(oeeBlock.availability ?? payload.availability, null);
const performance = toNumber(oeeBlock.performance ?? oeeBlock.performanceDisplay ?? oeeBlock.performanceAccumulated ?? payload.performance, null);
const quality = toNumber(oeeBlock.quality ?? payload.quality, null);
const oee = toNumber(oeeBlock.oee ?? oeeBlock.current ?? oeeBlock.value ?? payload.oee ?? payload.value, 0);
const dominantLoss = dominantLossFromMetrics(availability, performance, quality, payload.dominantLoss);
const localAction = String(payload.localAction || payload.recommendation || (oee < 0.6 ? "stabilize_local_" + dominantLoss : "maintain_operation"));
const localState = oee < 0.6 ? "critical" : oee < 0.75 ? "attention" : "stable";
const historyKey = cpsId + "_adaptive_history";
const previousHistory = Array.isArray(global.get(historyKey)) ? global.get(historyKey) : [];
let history = previousHistory.concat({
    ts: sourceTs,
    timestamp,
    oee,
    availability,
    performance,
    quality,
    dominantLoss,
    localAction,
    localState
}).slice(-windowSize);

const adaptiveLearningCps = buildSignals(history, windowSize);
history = history.map((entry, index) => {
    if (index !== history.length - 1) return entry;
    return Object.assign({}, entry, {
        temporalState: adaptiveLearningCps.temporalState,
        adaptiveAction: adaptiveLearningCps.adaptiveAction,
        strategyClass: adaptiveLearningCps.strategyClass,
        interventionEffectiveness: adaptiveLearningCps.interventionEffectiveness
    });
});
global.set(historyKey, history);
const adaptiveTimelineCps = buildTimeline(history, 8);

msg.topic = cpsId + "/local/adaptive";
msg.payload = {
    schemaVersion: "1.0",
    messageType: "cps_adaptive_local_intelligence",
    source: cpsId,
    cpsId,
    level: "level1",
    ts: now,
    timestamp: new Date(now).toISOString(),
    basedOn: {
        topic: inputTopic,
        sourceTs
    },
    localAssessment: {
        oee: round(oee, 4),
        availability: round(availability, 4),
        performance: round(performance, 4),
        quality: round(quality, 4),
        dominantLoss,
        localAction,
        localState
    },
    adaptiveLearningCps,
    adaptiveTimelineCps
};

node.status({ fill: adaptiveLearningCps.strategyClass === "escalated" ? "red" : adaptiveLearningCps.strategyClass === "adaptive" ? "yellow" : "green", shape: "dot", text: cpsId + " | " + adaptiveLearningCps.temporalState + " | n=" + history.length });
return msg;
